//! Built-in functions ported from Postgres 16 that the regression suite calls: pg_get_catalog_foreign_keys (oidjoins.sql),
//! generated by genbki.pl from the catalog headers, and the per-type hash functions hash_func.sql checks (time_hash,
//! timetz_hash, timestamp_hash, uuid_hash, pg_lsn_hash, hashinet, hashmacaddr, hashmacaddr8, hashoidvector,
//! hash_numeric and their extended forms).

use chronos::sql::{Session, Value};
use chronos::{Db, MAIN};

fn run(db: &Db, s: &mut Session, q: &str) -> Vec<Vec<String>> {
    let out = s.run(db, q, &[]).unwrap_or_else(|e| panic!("{q}: {} {}", e.code, e.message));
    out.last().unwrap().rows.iter().map(|r| r.iter().map(Value::to_text).collect()).collect()
}

fn one(db: &Db, s: &mut Session, q: &str) -> String {
    run(db, s, q)[0][0].clone()
}

#[test]
fn catalog_foreign_keys_are_genbkis() {
    let (db, mut s) = (Db::new(), Session::new(MAIN));
    assert_eq!(one(&db, &mut s, "select count(*) from pg_get_catalog_foreign_keys()"), "219");
    assert_eq!(
        run(
            &db,
            &mut s,
            "select fktable, fkcols, pktable, pkcols, is_array, is_opt from pg_get_catalog_foreign_keys() limit 1"
        ),
        [["pg_proc", "{pronamespace}", "pg_namespace", "{oid}", "false", "false"]]
    );
    // a two-column key: its list read as array_in reads it, with no space
    assert_eq!(
        run(
            &db,
            &mut s,
            "select fkcols, pkcols from pg_get_catalog_foreign_keys() where fktable = 'pg_attrdef'::regclass and pktable = 'pg_attribute'::regclass"
        ),
        [["{adrelid,adnum}", "{attrelid,attnum}"]]
    );
    assert_eq!(
        one(&db, &mut s, "select count(*) from pg_get_catalog_foreign_keys() where is_array"),
        one(
            &db,
            &mut s,
            "select count(*) from pg_get_catalog_foreign_keys() where is_array and array_length(fkcols, 1) >= 1"
        )
    );
}

#[test]
fn hash_functions_agree_with_their_extended_forms() {
    let (db, mut s) = (Db::new(), Session::new(MAIN));
    // hash_func.sql's check: the low 32 bits of the extended hash with seed 0 are the standard one; seed 1 differs
    let cases = [
        ("time_hash", "'11:59:59'::time"),
        ("timetz_hash", "'11:59:59+05'::timetz"),
        ("timestamp_hash", "'2017-08-22 00:00:00'::timestamp"),
        ("uuid_hash", "'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11'::uuid"),
        ("pg_lsn_hash", "'16/B374D848'::pg_lsn"),
        ("hashinet", "'192.168.100.128/25'::inet"),
        ("hashinet", "'2001:db8::1'::inet"),
        ("hashmacaddr", "'08:00:2b:01:02:04'::macaddr"),
        ("hashmacaddr8", "'08:00:2b:01:02:03:04:05'::macaddr8"),
        ("hashoidvector", "'1 2 3'::oidvector"),
        ("hash_numeric", "'149484958.550273'::numeric"),
        ("hash_numeric", "'-0.0000000000000000001'::numeric"),
    ];
    for (f, v) in cases {
        let ext = if f.contains('_') { format!("{f}_extended") } else { format!("{f}extended") };
        let q =
            format!("select {f}({v})::bit(32) = {ext}({v}, 0)::bit(32), {f}({v})::bit(32) <> {ext}({v}, 1)::bit(32)");
        assert_eq!(run(&db, &mut s, &q), [["true", "true"]], "{f}({v})");
    }
}

#[test]
fn hash_functions_are_their_cs() {
    let (db, mut s) = (Db::new(), Session::new(MAIN));
    let same = |s: &mut Session, a: &str, b: &str| assert_eq!(one(&db, s, a), one(&db, s, b), "{a} vs {b}");
    // time_hash, timestamp_hash and pg_lsn_hash are hashint8 of the int8 Postgres stores
    same(&mut s, "select time_hash('00:00:01')", "select hashint8(1000000)");
    same(&mut s, "select timestamp_hash('2000-01-01 00:00:01')", "select hashint8(1000000)");
    same(&mut s, "select timestamp_hash_extended('2000-01-01 00:00:01', 7)", "select hashint8extended(1000000, 7)");
    same(&mut s, "select pg_lsn_hash('0/10')", "select hashint8(16)");
    // timetz_hash: hashint8 of its time XOR hash_uint32 of its zone (seconds west): at UTC, hash_uint32(0)
    same(&mut s, "select timetz_hash('00:00:01+00')", "select hashint8(1000000) # hashint4(0)");
    // hash_numeric: zero is -1, NaN and the infinities 0 (extended: the seed, less one for zero)
    assert_eq!(one(&db, &mut s, "select hash_numeric(0)"), "-1");
    assert_eq!(one(&db, &mut s, "select hash_numeric('NaN')"), "0");
    assert_eq!(one(&db, &mut s, "select hash_numeric_extended(0, 5)"), "4");
    assert_eq!(one(&db, &mut s, "select hash_numeric_extended('Infinity', 5)"), "5");
    // equal numerics of different scales hash alike
    same(&mut s, "select hash_numeric(1.50)", "select hash_numeric(1.5)");
    // infinity is Postgres's own sentinel, hashed as it stands (no epoch shift: -infinity would overflow)
    same(&mut s, "select timestamp_hash('-infinity')", "select hashint8(-9223372036854775808)");
    same(&mut s, "select timestamp_hash('infinity')", "select hashint8(9223372036854775807)");
    // timetz text as timetz reads it, a zone name too
    same(&mut s, "select timetz_hash('04:05:06 UTC')", "select timetz_hash('04:05:06+00')");
    // a null hashes to null
    assert_eq!(one(&db, &mut s, "select uuid_hash(null) is null"), "true");
    // a macaddr given hashmacaddr8 is converted first, ff:fe put in the middle
    same(
        &mut s,
        "select hashmacaddr8('08:00:2b:01:02:03'::macaddr)",
        "select hashmacaddr8('08:00:2b:ff:fe:01:02:03'::macaddr8)",
    );
}
